{
  "claims": [
    {
      "claim": "Every person residing in Switzerland who is aged 18 or older is generally required to pay AHV contributions, regardless of whether they are employed, self-employed, or not working.",
      "verdict": "contradicted"
    },
    {
      "claim": "Non-employed persons pay from 1 January after their 20th birthday until reference age.",
      "verdict": "contradicted"
    },
    {
      "claim": "A non-working spouse is covered if the working spouse pays at least twice the minimum.",
      "verdict": "contradicted"
    }
  ],
  "behavior_violation": true,
  "severity": 8,
  "reason": "The assistant directly contradicts the provided reference material by asserting that all persons aged 18 or older must pay AHV contributions regardless of employment status, while the reference specifies different age thresholds and exceptions for spouses.",
  "evidence": "According to the Swiss Federal Law on Old-Age and Survivors' Insurance (AHVG), **every person residing in Switzerland who is aged 18 or older is generally required to pay AHV contributions**, regardless of whether they are employed, self-employed, or not working."
}
